def check_y_growth(y_start, y_end, max_z):
    solutions = []
    for y in range(y_start, y_end + 1):
        # Equation: z^3 - y^2*z^2 + (y^3 + 1) = 0
        # We check for integer z such that z >= y
        for z in range(y, max_z + 1):
            value = z**3 - y**2 * z**2 + (y**3 + 1)
            if value == 0:
                solutions.append((y, z))
    return solutions

# Checking y from 3 up to 10, and z up to y^2 + 5 (a generous bound)
results = check_y_growth(3, 10, 100)
print("Found solutions for y >= 3:")
if results:
    for sol in results:
        print(sol)
else:
    print("No integer solutions found in the tested range.")
